effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1.0 - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     float rand(vec2 co){
         return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
     }

     float sdUnevenCapsule( in vec2 p, in vec2 a, in vec2 b, in float r1, in float r2 )
     {
         vec2 pa = p-a, ba = b-a;
         float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
         return length( pa - ba*h ) - mix(r1, r2, h);
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = acTime;

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((-180.0+angle)*0.0174533);
     TanRyu += vec2((0.0-position.x), (-100.0+position.y))*vec2(-1.,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;
         float my_iTime = SPEED;
         float NEWFREQ = autop? freq + (acTime*1.5) : freq;
         float t_base = floor(NEWFREQ * my_iTime);

     	float t_off = 1.0 * rand(vec2(t_base, 134.0)) / freq;
         my_iTime += t_off;
         t_base += t_off;

         vec2 pos = vec2(1.0 * (2.0 * rand(vec2(t_base, 995.0)) - 1.0),
                         1.0 + 0.2 * (2.0 * rand(vec2(t_base, 46.0)) - 1.0));
         float r = 0.03;
         float a = radians(270.0) + radians(45.0) * (2.0 * rand(vec2(t_base, 13.0)) - 1.0);

         float d = 1e10;

         float sum_len = 0.0;

         float t = 1.0;
         // float t = 8.0 * (freq * my_iTime - t_base) / freq;
         // if ((t > 1. && t < 1.6) || t > 2.5)
             // t = 0.;

         float len_max = 8.0 * t;

         vec2 branch_1_pos;
         float branch_1_len = 0.0;
         float branch_1_r = 0.0;
     	float branch_1_a;

     	vec2 branch_2_pos;
         float branch_2_len = 0.0;
         float branch_2_r = 0.0;
     	float branch_2_a;

         for (int i = 0; i < int(LGT); ++i) {
             if (sum_len >= len_max) 
                 break;

             if (i == 3) {
                 branch_1_pos = pos;
                 branch_1_len = sum_len;
                 branch_1_r = 0.5 * r;
                 branch_1_a = radians(270.0) + radians(90.0) * (2.0 * rand(vec2(t_base, 13.0)) - 1.0);
             }

     		if (i == 6) {
                 branch_2_pos = pos;
                 branch_2_len = sum_len;
                 branch_2_r = 0.5 * r;
                 branch_2_a = radians(270.0) - radians(90.0) * (2.0 * rand(vec2(t_base, 17.0)) - 1.0);
             }

             float len = (LGT*0.01) + 0.18 * rand(vec2(300.0 + float(i) + t_base, 1337.0));
             float a_next = mix(a, radians(270.0) + radians(40.0) * (2.0 * rand(vec2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.9);

     		vec2 next = pos + len * vec2(cos(a), sin(a));
             float r_next = 0.9 * r;

         	d = min(d, sdUnevenCapsule(uv,
                                        pos, next,
                                        r, r_next));
             pos = next;
             r = r_next;
             a = a_next;

             sum_len = sum_len + len;
     	}

         for (int i = 0; i < 10; ++i) {
             if (branch_1_len >= len_max)
                 break;

     		float len = 0.07 + 0.07 * rand(vec2(300.0 + float(i) + t_base, 1337.0));
             float a_next = mix(radians(270.0), branch_1_a + radians(40.0) * (2.0 * rand(vec2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.5);

     		vec2 next = branch_1_pos + len * vec2(cos(branch_1_a), sin(branch_1_a));
             float r_next = 0.9 * branch_1_r;

             d = min(d, sdUnevenCapsule(uv, branch_1_pos, next, branch_1_r, r_next));

     		branch_1_pos = next;
             branch_1_r = r_next;
             branch_1_a = a_next;

             branch_1_len += len;
         }

         for (int i = 0; i < 10; ++i) {
             if (branch_2_len >= len_max)
                 break;

     		float len = 0.07 + 0.07 * rand(vec2(300.0 + float(i) + t_base, 1337.0));
             float a_next = mix(radians(270.0), branch_2_a + radians(40.0) * (2.0 * rand(vec2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.5);

     		vec2 next = branch_2_pos + len * vec2(cos(branch_2_a), sin(branch_2_a));
             float r_next = 0.9 * branch_2_r;

             d = min(d, sdUnevenCapsule(uv, branch_2_pos, next, branch_2_r, r_next));

     		branch_2_pos = next;
             branch_2_r = r_next;
             branch_2_a = a_next;

             branch_2_len += len;
         }

         vec3 sky =
               0.2 * vec3(0, 0, 1) * clamp(sum_len, 0., 1.0)
             + 0.1 * vec3(1, 1, 1) * clamp(sum_len - 0.8, 0., 1.0);

         fragColor = vec4(sky
                          + clamp(0.9 - sqrt(d + 0.01), 0., 1.0) * sky * max(0.9 * uv.y + 2., 0.0)
                          + vec3(smoothstep(0.0, -.01, d)), 1.0);

 	// vec4 factor = mix(texColorX,fragColor,1.0);

 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         vec4 gradmap;
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    vec4 factor = mix(texColorX,gradmap,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.0-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
